            new Quote { Id = "https://en.wikiquote.org/wiki/F._Scott_Fitzgerald", Text = "It was a marriage of love. He was sufficiently spoiled to be charming; she was ingenuous enough to be irresistible.", Author = "F. Scott Fitzgerald" },
            new Quote { Id = "https://en.wikiquote.org/wiki/F._Scott_Fitzgerald", Text = "Summer was gone and now Indian summer. The grass was cold and there was no mist and no dew. After he left she would go in and light the gas and close the shatters, and he would go down the path and on to the village. To these two life had come quickly and gone, leaving not bitterness, but pity; not disillusion, but only pain.", Author = "F. Scott Fitzgerald" },
