            new Quote { Id = "https://en.wikiquote.org/wiki/F._Scott_Fitzgerald", Text = "Whenever you feel like criticizing any one... just remember that all the people in this world haven't had the advantages that you've had.", Author = "F. Scott Fitzgerald" },
