            new Quote { Id = "https://en.wikiquote.org/wiki/F._Scott_Fitzgerald", Text = "In a real dark night of the soul it is always three o'clock in the morning, day after day.", Author = "F. Scott Fitzgerald" },
            new Quote { Id = "https://en.wikiquote.org/wiki/F._Scott_Fitzgerald", Text = "Before I go on with this short history, let me make a general observation – the test of a first-rate intelligence is the ability to hold two opposed ideas in the mind at the same time, and still retain the ability to function.", Author = "F. Scott Fitzgerald" },
            new Quote { Id = "https://en.wikiquote.org/wiki/F._Scott_Fitzgerald", Text = "Genius goes around the world in its youth incessantly apologizing for having large feet. What wonder that later in life it should be inclined to raise those feet too swiftly to fools and bores.", Author = "F. Scott Fitzgerald" },
