            new Quote { Id = "https://en.wikiquote.org/wiki/F._Scott_Fitzgerald", Text = "It isn't given for us to know those rare moments when people are wide open and the lightest touch can wither or heal. A moment too late and we can never reach them any more in this world. They will not be cured by our most efficacious drugs or slain with our sharpest swords.", Author = "F. Scott Fitzgerald" },
