            new Quote { Id = "https://en.wikiquote.org/wiki/F._Scott_Fitzgerald", Text = "Once one is caught up into the material world not one person in ten thousand finds the time to form literary taste, to examine the validity of philosophic concepts for himself, or to form what, for lack of a better phrase, I might call the wise and tragic sense of life.", Author = "F. Scott Fitzgerald" },
